#include <cuda_runtime.h>
#define main legacy_main
#include "../filter-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
int main(int argc,char**argv){int n=262144,repeats=argc>1?atoi(argv[1]):20;std::vector<int> input(n),expected,output,values(n);for(int i=0;i<n;i++){input[i]=int((int64_t(i)*65537+17)%n)-n/2;if(input[i]>0)expected.push_back(input[i]);}std::sort(expected.begin(),expected.end());int *src,*dst,*count;CK(cudaMalloc(&src,n*4));CK(cudaMalloc(&dst,n*4));CK(cudaMalloc(&count,4));CK(cudaMemcpy(src,input.data(),n*4,cudaMemcpyHostToDevice));auto launch=[&](int mode){CK(cudaMemset(count,0,4));if(mode==0)filter<<<n/256,256>>>(dst,count,src,n);else filter2<<<n/256,256>>>(dst,count,src,n);};launch(0);launch(1);CK(cudaDeviceSynchronize());bool all=true;
for(int trial=1;trial<=5;trial++){double times[2]={};bool ok=true;output.clear();for(int mode=0;mode<2;mode++){CK(cudaMemset(dst,0,n*4));CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();for(int rep=0;rep<repeats;rep++)launch(mode);CK(cudaDeviceSynchronize());times[mode]=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeats;int k;CK(cudaMemcpy(&k,count,4,cudaMemcpyDeviceToHost));if(k!=expected.size()){fprintf(stderr,"bad count%d\n",k);return 1;}CK(cudaMemcpy(values.data(),dst,k*4,cudaMemcpyDeviceToHost));std::sort(values.begin(),values.begin()+k);ok&=std::equal(expected.begin(),expected.end(),values.begin());output.push_back(k);output.insert(output.end(),values.begin(),values.begin()+k);}all&=ok;char file[100];sprintf(file,"filter_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),4,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":0,\"max_rel_error\":0,\"timing_region\":\"sum_shared_and_global_compaction_including_counter_reset_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"mode_times_seconds\":[%.12g,%.12g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,times[0]+times[1],ok?"true":"false",int(output.size()),repeats,times[0],times[1],file,int(output.size()));}CK(cudaFree(src));CK(cudaFree(dst));CK(cudaFree(count));puts(all?"PASS":"FAIL");return all?0:1;}
